"""Write legacy-strict three-value profiles and immutable requests for the 96 colours."""
import argparse,hashlib,json,sys
from pathlib import Path
from v7_human_roster_materials import json_write
def artifact(T,path):
 return {'root_id':'v7_human_roster_20261004','path':str(path.relative_to(T)),'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'size_bytes':path.stat().st_size}
def run(T,B):
 sys.path.insert(0,str(B/'tools'))
 from controlled_source_asset_schema import validate_attribute_profile,build_instance_request,profile_sha256
 selection=json.loads((T/'registrations/selection.json').read_text());profiles=[];requests=[];mapping=[]
 labels={'red':'红','green':'绿','blue':'蓝','yellow':'黄','white':'白','black':'黑'}
 for row in selection['avatars']:
  if not row['controlled_color']:continue
  aid=row['asset_id'];base=T/'assets/metric'/aid/'runtime.glb';mask=T/'masks'/aid/'mask_registry.json';build=json.loads((T/'assets/rocketbox'/aid/'build.json').read_text());pose=json.loads((T/'assets/runtime'/aid/'black/poses.json').read_text());height=pose['poses']['stand']['bounds_max_m'][1]*100
  for i,domain in enumerate(selection['color_domains']):
   pid=aid+'_shirt_set_'+str(i+1)+'_v1';profile={'schema':'avengine_attribute_profile_v1','profile_schema_id':pid,'profile_revision':'20261004','asset_class':'human','lineage_group_id':aid,'state_classification':'research_candidate','taxonomy':{'species':'human','life_stage':'adult','gender':row['gender']},'base_template':{'template_id':aid,'kind':'rocketbox_avatar','artifact':artifact(T,base),'provenance_status':'verified','usage_scope':'research_candidate'},'fixed_attributes':{'avatar_identity':aid,'uniform_policy':'casual_shirt_only'},'sampled_attribute_domains':{'shirt_main_color':domain},'forbidden_combinations':[],'generation_contract':{'route':'rocketbox_material_v1','material_plan_schema':'rocketbox_material_edit_plan_v1','material_bindings':{'shirt_main_color':{'semantic_mask':'shirt_main_color','mask_registry':artifact(T,mask),'source_texture_role':'body_base_color','operation':'replace_base_color_preserve_pbr_detail_v1','palette':{c:{'srgb_u8':selection['palette_srgb'][c]}for c in domain}}},'flux_texture_detail':{'enabled':False,'policy':'approved_mask_optional_only'}},'target_physical_profiles':{'profile_id':aid+'_authored_height_v1','control_attribute':None,'measurement':'height_cm','mode':'authored','reference_value_cm':height,'reference_provenance':{'status':'verified','source_id':aid,'artifact':artifact(T,T/'assets/runtime'/aid/'black/poses.json'),'notes':'Authored metric standing geometry; native Habitat and UE evidence is recorded separately.'},'values':{'fixed':{'actor_scale':1.0,'target_value_cm':height,'tolerance_cm':1.5}}},'rig_profile':{'profile_id':aid+'_rocketbox_rig_v1','skeleton_family':build['source_mesh_metrics']['vertex_group_names'][0].split()[0],'actions':['Walking','Standing_Idle'],'front_axis':'positive_z'},'acoustic_profile':{'profile_id':'v7_human_speech_mapping_v1','default_event_class':'human_speech','allowed_event_classes':['human_speech'],'selection_attributes':['avatar_identity']},'locked_attributes':['eyes','headwear','eyewear','accessories','garment_geometry','topology','uv','skeleton'],'qa_contract':{'subject_label':'人物','attributes':{'shirt_main_color':{'kind':'categorical','label':'上衣主色','value_labels':{c:labels[c]for c in domain},'identification_question':'{instance_label} 的上衣主色是什么？'}}}}
   profile=validate_attribute_profile(profile);dest=T/'registrations/strict_profiles'/(pid+'.json');json_write(dest,profile);profiles.append({'profile_schema_id':pid,'path':str(dest.relative_to(T)),'profile_sha256':profile_sha256(profile),'lineage_group_id':aid})
   for j,c in enumerate(domain):
    request=build_instance_request(profile,{'shirt_main_color':c},batch_seed=20261004,sample_ordinal=j);dest=T/'registrations/instance_requests'/(request['instance_id']+'.json');json_write(dest,request);requests.append(str(dest.relative_to(T)));mapping.append({'major_id':aid,'variant_id':aid+'_'+c+'_v1','profile_schema_id':pid,'instance_id':request['instance_id'],'request_path':str(dest.relative_to(T))})
 json_write(T/'registrations/strict_profiles/index.json',{'schema':'avengine_v7_strict_profile_index_v1','profiles':profiles,'requests':requests,'bindings':mapping,'scope':'validated profile and request metadata; mask registry uses this task custom UV registry; re-execution is via v7_human_roster_materials.py, not a claim of legacy pipeline step6/global registration','sit_note':'The legacy strict human rig schema admits Walking/Standing_Idle only; Sitting_Idle support is declared separately in the v7 roster.'})
 json_write(T/'evidence/strict_profile_validation.json',{'profile_count':len(profiles),'request_count':len(requests),'validator':str(B/'tools/controlled_source_asset_schema.py'),'validator_sha256':hashlib.sha256((B/'tools/controlled_source_asset_schema.py').read_bytes()).hexdigest(),'all_pass':True})
 print('STRICT_PROFILES',len(profiles),'IMMUTABLE_REQUESTS',len(requests))
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--task-root',type=Path,required=True);p.add_argument('--legacy-root',type=Path,required=True);a=p.parse_args();run(a.task_root,a.legacy_root)
